ee:message.ee:set-payload:
%dw 2.0
import lowerKeys from modules::util
output application/json
var rows = lowerKeys(payload)
var cfg = readUrl("classpath://config/entitlements.json", "application/json")
---
{
	contract: cfg.contract,
	operatingMode: cfg.operating_mode,
	computedAt: rows[0].computed_at,
	entitlements: rows filter ((r) -> r.usage_model != "MONITOR"),
	monitoring: rows filter ((r) -> r.usage_model == "MONITOR")
}

db:select.db:input-parameters:
#[{
	status: attributes.queryParams.status default "unresolved",
	max_rows: (attributes.queryParams.limit default "200") as Number
}]

#[{
	risk: attributes.queryParams.risk default "all",
	max_rows: (attributes.queryParams.limit default "300") as Number
}]

ee:message.ee:set-payload:
%dw 2.0
output application/json
---
vars.settings ++ {
	"readOnly": {
		"email.enabled": p('email.enabled') == "true",
		"alerts.warningPct": p('alerts.warningPct') as Number,
		"alerts.criticalPct": p('alerts.criticalPct') as Number,
		"scheduler.intervalMinutes": p('scheduler.collectAll.frequencyMinutes') as Number,
		"app.baseUrl": p('app.baseUrl')
	}
}

ee:variables.ee:set-variable:
%dw 2.0
output application/java
var b = payload
var emailRegex = /^[^@\s]+@[^@\s]+\.[^@\s]+$/
---
flatten([
	if ((b."alerts.email.to" != null) and not (b."alerts.email.to" is Array)) ["alerts.email.to must be a list"] else [],
	if (b."alerts.email.to" is Array) ((b."alerts.email.to" filter ((e) -> not ((e as String) matches emailRegex))) map ((e) -> "invalid email: $(e)")) else [],
	if ((b."audit.exclude_actions" != null) and not (b."audit.exclude_actions" is Array)) ["audit.exclude_actions must be a list"] else [],
	if ((b."audit.auto_resolve_days" != null) and not ((b."audit.auto_resolve_days" is Number) and (b."audit.auto_resolve_days" > 0))) ["audit.auto_resolve_days must be a positive number"] else [],
	if ((b."audit.max_lookback_hours" != null) and not ((b."audit.max_lookback_hours" is Number) and (b."audit.max_lookback_hours" > 0))) ["audit.max_lookback_hours must be a positive number"] else []
])
